export default function NewsScreen() {
  const [activeFilter, setActiveFilter] = useState('all');
  const [selectedNews, setSelectedNews] = useState<typeof newsData[0] | null>(null);
  const [modalVisible, setModalVisible] = useState(false);
  const [refreshing, setRefreshing] = useState(false);

  const onRefresh = React.useCallback(() => {
    setRefreshing(true);
    // Simulate API call to fetch latest news
    setTimeout(() => {
      setRefreshing(false);
      // In production, fetch new data here
    }, 1500);
  }, []);

  const handleNewsPress = (news: typeof newsData[0]) => {
    setSelectedNews(news);
    setModalVisible(true);
  };

  const filteredNews = newsData.filter(news => 
    activeFilter === 'all' || news.filter === activeFilter
  );

  return (
    <ScreenLayout 
      title="Latest News" 
      subtitle="Stay informed with live updates on the dam"
    >
      <View className="flex-1 bg-gray-50">
        {/* Filter Tabs */}
        <NewsFilterTabs 
          activeFilter={activeFilter}
          onFilterChange={setActiveFilter}
        />

        {/* News List */}
        <ScrollView 
          className="flex-1 px-4"
          showsVerticalScrollIndicator={false}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={onRefresh}
              tintColor="#2563eb"
              title="Pull to refresh"
            />
          }
        >
          {filteredNews.map((news) => (
            <NewsCard
              key={news.id}
              {...news}
              onPress={() => handleNewsPress(news)}
            />
          ))}
          
          <View className="h-6" />
        </ScrollView>

        {/* News Detail Modal */}
        <NewsDetailModal
          visible={modalVisible}
          onClose={() => setModalVisible(false)}
          news={selectedNews}
        />
      </View>
    </ScreenLayout>
  );
}